-- Run AFTER importing products
INSERT INTO recipes(title,slug,intro,steps) VALUES
('Party Jollof Rice','party-jollof-rice','The smoky, spicy rice every celebration needs.','1. Blend the tomatoes, red pepper and scotch bonnet until smooth, then boil the mixture until it thickens and the water cooks off.\n2. Heat oil in a large pot, fry sliced onions until soft, then stir in the tomato paste and fry for a few minutes.\n3. Add the blended pepper mix, curry powder, thyme, bay leaves and seasoning cubes. Cook until the oil rises to the top.\n4. Wash the rice and add it with enough stock to just cover. Stir well, cover tightly and cook on low heat.\n5. Let it steam until the rice is tender, stirring once or twice. Taste and adjust the salt.'),
('Egusi Soup','egusi-soup','Rich melon seed soup, perfect with pounded yam, eba or amala.','1. Boil the goat meat and stockfish with onion, seasoning cubes and a little water until tender.\n2. Heat palm oil in a separate pot, add chopped onions and fry briefly. Add the ground egusi and stir until it forms small curds.\n3. Pour in the meat stock, add the meat, stockfish, crayfish, pepper and locust beans. Simmer for 15 to 20 minutes.\n4. Add chopped spinach, stir and cook for 5 more minutes. Serve hot.'),
('Beans and Fried Plantain','beans-and-plantain','A comforting classic, ready in under an hour.','1. Wash and boil the beans until soft.\n2. Fry onions and pepper flakes in palm oil, then stir in the beans and simmer until thick.\n3. Slice ripe plantain and fry until golden.\n4. Serve the beans with the fried plantain on the side.');
INSERT INTO recipe_items(recipe_id,product_id,qty) SELECT r.id,p.id,x.q FROM recipes r JOIN (
 SELECT 'party-jollof-rice' s,'Long Grain Parboiled Rice' n,1 q UNION ALL SELECT 'party-jollof-rice','Tomato Paste (Gino)',3 UNION ALL SELECT 'party-jollof-rice','Fresh Tomatoes',1 UNION ALL SELECT 'party-jollof-rice','Red Pepper (Tatashe)',0.5 UNION ALL SELECT 'party-jollof-rice','Scotch Bonnet (Ata Rodo)',0.5 UNION ALL SELECT 'party-jollof-rice','Onions',1 UNION ALL SELECT 'party-jollof-rice','Vegetable Oil',1 UNION ALL SELECT 'party-jollof-rice','Maggi Star Seasoning Cubes',1 UNION ALL SELECT 'party-jollof-rice','Curry Powder',1 UNION ALL SELECT 'party-jollof-rice','Dried Thyme',1 UNION ALL SELECT 'party-jollof-rice','Bay Leaves',1
 UNION ALL SELECT 'egusi-soup','Egusi (Ground Melon Seeds)',1 UNION ALL SELECT 'egusi-soup','Red Palm Oil',1 UNION ALL SELECT 'egusi-soup','Goat Meat (Cut)',1 UNION ALL SELECT 'egusi-soup','Stockfish Pieces',0.5 UNION ALL SELECT 'egusi-soup','Ground Crayfish',1 UNION ALL SELECT 'egusi-soup','Spinach (Efo Tete)',2 UNION ALL SELECT 'egusi-soup','Onions',1 UNION ALL SELECT 'egusi-soup','Maggi Star Seasoning Cubes',1 UNION ALL SELECT 'egusi-soup','Dry Pepper Flakes',1 UNION ALL SELECT 'egusi-soup','Iru (Locust Beans)',1
 UNION ALL SELECT 'beans-and-plantain','Honey Beans (Oloyin)',1 UNION ALL SELECT 'beans-and-plantain','Ripe Plantain',1 UNION ALL SELECT 'beans-and-plantain','Red Palm Oil',1 UNION ALL SELECT 'beans-and-plantain','Onions',0.5 UNION ALL SELECT 'beans-and-plantain','Dry Pepper Flakes',1
) x ON x.s=r.slug JOIN products p ON p.name=x.n;
